;   4 vibrato: bits 0-2 speed, bits 4-6 depth shift   5 bits 4-7 vibrato delay (ticks)
SfxInstrTbl:
        .byte $80, $00, $04, $05, $00, $00   ; 0
        .byte $80, $02, $03, $04, $00, $00   ; 1
        .byte $80, $00, $06, $03, $00, $00   ; 2
        .byte $00, $00, $01, $00, $00, $00   ; 3
        .byte $80, $00, $03, $02, $00, $00   ; 4
        .byte $80, $06, $0B, $01, $00, $00   ; 5
        .byte $00, $00, $04, $05, $00, $00   ; 6
        .byte $40, $00, $04, $05, $00, $00   ; 7
        .byte $80, $00, $04, $05, $00, $00   ; 8
        .byte $80, $06, $06, $06, $00, $00   ; 9
        .byte $80, $01, $06, $07, $00, $00   ; 10
        .byte $00, $07, $01, $08, $00, $00   ; 11
        .byte $00, $00, $01, $00, $00, $00   ; 12
        .byte $C0, $00, $09, $00, $00, $00   ; 13
        .byte $00, $00, $06, $0A, $00, $00   ; 14
        .byte $C0, $08, $09, $0B, $00, $00   ; 15
        .byte $80, $00, $07, $0C, $00, $00   ; 16
        .byte $80, $00, $07, $0C, $00, $00   ; 17
        .byte $00, $00, $03, $0D, $00, $00   ; 18
        .byte $80, $06, $06, $0E, $00, $00   ; 19
        .byte $00, $00, $0E, $0F, $00, $00   ; 20
        .byte $40, $00, $07, $10, $00, $00   ; 21

; SFX pitch envelopes: pointers (1-based numbers in the instruments; entry i = env i+1)
